/**\n * Data Models for IPTV Android TV App\n * Define all data structures matching the web app\n * Use these models throughout your Kotlin application\n */\n\npackage com.example.iptvapp.data.model\n\nimport androidx.compose.runtime.Immutable\n\n// ==================== COUNTRY MODEL ====================\n/**\n * Represents a country with list of TV channels\n * @param id Unique identifier (\"usa\", \"italy\", etc.)\n * @param name Display name (\"United States\", \"Italy\", etc.)\n * @param flag Emoji flag (\"🇺🇸\", \"🇮🇹\", etc.)\n * @param channels Number of available channels\n */\n@Immutable\ndata class Country(\n    val id: String,\n    val name: String,\n    val flag: String,\n    val channels: Int\n)\n\n// ==================== SHOW/CHANNEL MODEL ====================\n/**\n * Represents a TV channel or show\n * @param id Unique identifier\n * @param name Channel name (\"Nat Geo Wild HD\", \"Netflix\", etc.)\n * @param channel Channel provider (\"National Geographic\", \"Netflix\", etc.)\n * @param logo Display logo text or emoji\n * @param views Viewer count (\"12.5M\", \"+8.2M\", etc.)\n * @param quality List of quality indicators ([\"4K\", \"EPG\"], [\"HD\", \"EPG\"], etc.)\n * @param isPremium Whether channel is premium (marked with $)\n * @param favorite Whether user has marked as favorite\n * @param description Channel description\n * @param currentlyPlaying What's currently playing on the channel\n * @param progress Video playback progress (0-100%)\n * @param thumbnail Thumbnail image URL\n */\n@Immutable\ndata class Show(\n    val id: String,\n    val name: String,\n    val channel: String,\n    val logo: String,\n    val views: String,\n    val quality: List<String>,\n    val isPremium: Boolean = false,\n    val favorite: Boolean = false,\n    val description: String = \"\",\n    val currentlyPlaying: String = \"\",\n    val progress: Int = 0,\n    val thumbnail: String = \"\"\n)\n\n// ==================== USER SETTINGS MODEL ====================\n/**\n * User preferences and app settings\n */\n@Immutable\ndata class UserSettings(\n    val videoQuality: String = \"1080p\",           // 480p, 720p, 1080p, 4K\n    val language: String = \"English\",            // English, Spanish, French, Portuguese\n    val audioFormat: String = \"Stereo\",          // Stereo, Surround, Dolby Atmos\n    val subtitles: String = \"On\",                // On, Off, Auto\n    val brightness: Int = 100,                   // 0-100\n    val volume: Int = 80,                        // 0-100\n    val autoPlay: Boolean = true,                // Auto-play next episode\n    val remember Last Watched: Boolean = true    // Remember playback position\n)\n\n// ==================== PLAYBACK STATE MODEL ====================\n/**\n * Current playback state\n */\n@Immutable\ndata class PlaybackState(\n    val isPlaying: Boolean = false,\n    val currentTime: Long = 0,                   // Milliseconds\n    val duration: Long = 0,                      // Milliseconds\n    val bufferedTime: Long = 0,                  // Milliseconds\n    val isBuffering: Boolean = false,\n    val error: String? = null                    // Error message if any\n)\n\n// ==================== FOCUS STATE MODEL ====================\n/**\n * UI Focus state for remote navigation\n */\nenum class FocusZone {\n    SIDEBAR,      // Country/menu selection\n    CONTENT,      // Channel list\n    PLAYER,       // Video player\n    SEARCH,       // Search input\n    SETTINGS      // Settings menu\n}\n\n@Immutable\ndata class UIFocusState(\n    val currentZone: FocusZone = FocusZone.CONTENT,\n    val focusedIndex: Int = 0,                   // Index within the zone\n    val isSearchActive: Boolean = false          // Whether search input is active\n)\n\n// ==================== SEARCH RESULT MODEL ====================\n/**\n * Search results with filters\n */\n@Immutable\ndata class SearchResult(\n    val query: String,\n    val shows: List<Show>,\n    val totalCount: Int,\n    val filterType: FilterType = FilterType.ALL\n)\n\nenum class FilterType {\n    ALL,          // All channels\n    HD,           // Only HD channels\n    ULTRA_4K,     // Only 4K channels\n    FAVORITE,     // Only favorites\n    PREMIUM       // Only premium channels\n}\n\n// ==================== PREDEFINED DATA ====================\n/**\n * Country list - Complete list of available countries\n */\nobject CountryData {\n    val countries = listOf(\n        Country(\"usa\", \"United States\", \"🇺🇸\", 147),\n        Country(\"china\", \"China\", \"🇨🇳\", 156),\n        Country(\"brazil\", \"Brazil\", \"🇧🇷\", 64),\n        Country(\"germany\", \"Germany\", \"🇩🇪\", 45),\n        Country(\"italy\", \"Italy\", \"🇮🇹\", 52),\n        Country(\"france\", \"France\", \"🇫🇷\", 41),\n        Country(\"ukraine\", \"Ukraine\", \"🇺🇦\", 38),\n        Country(\"portugal\", \"Portugal\", \"🇵🇹\", 33),\n        Country(\"south-africa\", \"South Africa\", \"🇿🇦\", 29)\n    )\n}\n\n/**\n * Sample shows/channels - Use as seed data or for testing\n */\nobject ShowData {\n    val shows = listOf(\n        Show(\n            id = \"1\",\n            name = \"Nat Geo Wild HD\",\n            channel = \"National Geographic\",\n            logo = \"NAT GEO WILD HD\",\n            views = \"+8.2M\",\n            quality = listOf(\"HD\", \"EPG\"),\n            description = \"Explore the wild world with stunning wildlife documentaries\",\n            currentlyPlaying = \"Animals and Nature\",\n            progress = 65,\n            thumbnail = \"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=800&h=600&fit=crop\"\n        ),\n        Show(\n            id = \"2\",\n            name = \"Disney Channel\",\n            channel = \"The Walt Disney Company\",\n            logo = \"DISNEY CHANNEL\",\n            views = \"850K\",\n            quality = listOf(\"4K\", \"EPG\", \"$\"),\n            isPremium = true,\n            favorite = true,\n            description = \"Premium entertainment for the whole family\"\n        ),\n        Show(\n            id = \"3\",\n            name = \"HBO Family\",\n            channel = \"HBO\",\n            logo = \"HBO\",\n            views = \"1.7M\",\n            quality = listOf(\"HD\", \"EPG\"),\n            description = \"Premium movies and series for family entertainment\"\n        ),\n        Show(\n            id = \"4\",\n            name = \"Netflix Original\",\n            channel = \"Netflix\",\n            logo = \"NETFLIX\",\n            views = \"12.5M\",\n            quality = listOf(\"4K\", \"HD\", \"EPG\"),\n            favorite = true,\n            description = \"Binge-worthy series and blockbuster movies\"\n        ),\n        Show(\n            id = \"5\",\n            name = \"Discovery Channel\",\n            channel = \"Discovery\",\n            logo = \"DISCOVERY\",\n            views = \"3.2M\",\n            quality = listOf(\"HD\", \"EPG\"),\n            description = \"Fascinating documentaries and real-life adventure\"\n        ),\n        Show(\n            id = \"6\",\n            name = \"BBC News\",\n            channel = \"BBC\",\n            logo = \"BBC\",\n            views = \"5.4M\",\n            quality = listOf(\"HD\"),\n            description = \"Latest news from around the world\"\n        ),\n        Show(\n            id = \"7\",\n            name = \"ESPN Sports\",\n            channel = \"ESPN\",\n            logo = \"ESPN\",\n            views = \"7.8M\",\n            quality = listOf(\"4K\", \"EPG\"),\n            favorite = true,\n            description = \"Live sports events and analysis\"\n        ),\n        Show(\n            id = \"8\",\n            name = \"Fashion TV HD\",\n            channel = \"Fashion TV\",\n            logo = \"FTV\",\n            views = \"2.1M\",\n            quality = listOf(\"HD\", \"EPG\"),\n            description = \"Fashion shows and lifestyle content\"\n        )\n    )\n}\n\n// ==================== SETTINGS PRESETS ====================\n/**\n * Video quality options\n */\nobject VideoQualityOptions {\n    const val QUALITY_480P = \"480p\"\n    const val QUALITY_720P = \"720p HD\"\n    const val QUALITY_1080P = \"1080p Full HD\"\n    const val QUALITY_4K = \"4K Ultra HD\"\n    \n    val allOptions = listOf(\n        QUALITY_480P,\n        QUALITY_720P,\n        QUALITY_1080P,\n        QUALITY_4K\n    )\n}\n\n/**\n * Language options\n */\nobject LanguageOptions {\n    const val ENGLISH = \"English\"\n    const val SPANISH = \"Spanish\"\n    const val FRENCH = \"French\"\n    const val PORTUGUESE = \"Portuguese\"\n    \n    val allOptions = listOf(\n        ENGLISH,\n        SPANISH,\n        FRENCH,\n        PORTUGUESE\n    )\n}\n\n/**\n * Audio format options\n */\nobject AudioFormatOptions {\n    const val STEREO = \"Stereo\"\n    const val SURROUND = \"Surround\"\n    const val DOLBY_ATMOS = \"Dolby Atmos\"\n    \n    val allOptions = listOf(\n        STEREO,\n        SURROUND,\n        DOLBY_ATMOS\n    )\n}\n\n/**\n * Subtitle options\n */\nobject SubtitleOptions {\n    const val OFF = \"Off\"\n    const val ON = \"On\"\n    const val AUTO = \"Auto\"\n    \n    val allOptions = listOf(\n        OFF,\n        ON,\n        AUTO\n    )\n}\n\n// ==================== TYPE ALIASES ====================\ntypealias ChannelId = String\ntypealias CountryId = String\ntypealias UserId = String\n"
}
